#!/usr/bin/bash
############################################################################################################
#Product: Load Helper Script
#Version: 1.0.0.4
#Author : Arun Kumar
#License: Plintron Global Technology
#
#INFORMATION:
#-----------
#This script will read input from the loadconfg.sh file.
#It can calculate the disk space used and clean up.
#It can run any number of instances and products as configured in the loadconfg.sh file.
#It can maintain log files generated by application by either zip or  delete.
#It can capture the tcap measurements and memory utilizations
#It also monitors the applications and restarts them if dead.
#It generates hourly and minutes based statistics report.
#The report is also generated in CSV file for ease of viewing in windows system
#It writes a report which contains data about any abnormality occurences. i.e application restart etc..
#
#WARNING:
#--------
#Editing this file is strictly not advisable.
#
############################################################################################################
#Version 1.0.0.2 changes:
#-----------------------
#Included "move" option for log handling
#This will move logs to destination folder if the minimum logs to be maintained exceeds.
#Error will be thrown if no log path or invalid path is defined in configuration file and user selects move option
#Version 1.0.0.3 changes:
#-----------------------
#Included stop_load.sh to stop the script apart from ctrl+c
#If the script is not responding for ctrl+c then run this script
#Version 1.0.0.4 changes:
#-----------------------
# Bug fixing
#Version 1.0.0.5 changes:
#-----------------------
#Server stats, Instances stats and TcapMeasurements is now implemented for all
#products (main + dependent products). Its up to the user to enable and 
#disable during startup
##############################################################################################################



parent=$$
clear;
curr_path=`pwd`;
