disk_enable_input () {

	echo -n "Do you want to view the top 10 folders thats occupying the disk space [y/n]: "
	read disk_handle;
	if [ $disk_handle = "y" -o $disk_handle = "Y"  -o $disk_handle = "n" -o $disk_handle = "N" ] 2>/dev/null
	then
		:
	else
		echo "Invalid Entry";
		disk_enable_input;
	fi
	}
disk_enable_input;

#Disk space handling

if [ $disk_handle = "y" -o $disk_handle = "Y" ]
then

rm -rf tmp;
#################Checking the disk space for log folder########################
[[ ! -d $log_path ]] && echo "folder $log_path doesnt exists" && exit;
curr_path=`pwd`;
#convert Gb to Kb
log_path_min_size=`expr $log_path_min_size_Gb \* 1048576`
log_path_max_size=`expr $log_path_max_size_Gb \* 1048576`

actual_avail=`df -k $log_path | grep "%" | awk {'print $4'}`;

#convert KB to Gb
actual_avail_Gb=`df -h $log_path | grep "%" | awk {'print $4'}`;
top_10 () {
actual_avail=`df -k $log_path | grep "%" | awk {'print $4'}`;
actual_avail_Gb=`df -h $log_path | grep "%" | awk {'print $4'}`;
if [ $actual_avail -lt $log_path_min_size ]
then
   echo "Space $actual_avail_Gb avaliable is less than expected $log_path_min_size_Gb Gigabytes"
   parent_dir=`df -k $log_path | grep "%" | awk {'print $6'}`;
   echo "Calculating Top 10 folders which occupy most of the space...
This may take a while... (average time taken is: 15 to 30 Sec) Pls wait...
It takes longer time if the server is heavily occupied by some other Process/Application.."
   du -o $parent_dir | sort -n -r | head -10 | awk {'print $2'} > tmp;
   cat tmp | xargs  du -sh > tmp_size;
i=0;
echo "";
while read line
do
echo "$i)  $line";
i=`expr $i + 1`;
done < tmp_size
rm tmp_size;
raw_del_list=(`cat tmp`);
unset del_list[*];

selected_delete () {
echo -n "From the above list, enter how many folders do you want to delete: "
read nof;

case $nof in
[0-9]|[0-9][0-9])
                 [[ $nof -gt 10 ]] && echo "Out of range" && selected_delete;;
*) echo "invalid entry"; selected_delete;;
esac

i=0;
while [ $i -lt $nof ]
do
  echo -n "`expr $i + 1`. Enter the corresponding folder number from the above list : "
  read a;
  case $a in
  [0-9])
       del_list[$i]=${raw_del_list[ $a ]};;
  *) echo "invalid entry"; selected_delete;;
  esac
  i=`expr $i + 1`;
done

clear;
echo "You have choosen to delete the following directory contents :"
echo "";
for b in ${del_list[*]}
do
  echo $b;
done
echo "";
echo -n "Are you sure you want to clear the contents of the above directory? [y/n] : ";
read yn
if [ $yn != "y" -o $yn != "y" ]
then
  echo "ok Good Bye !!!" ;
   exit;
fi
}

delete () {
for b in ${del_list[*]}
do
echo "Clearing contents of  $b";
echo "This may take a while..";
cd $b
rm -f *.log*
rm -f *.tdr*
rm -f *.cdr*
cd $curr_path;
done
}

clear_contents () {

echo ""; echo "";

echo "what do you want to perform?
1. Clear contents of all the above listed directories
2. Clear contents of only selected directories
3. Do nothing, proceed as such
4. Quit the session
"
echo -n "Enter your choice: "
read choice
export flag=0;
case $choice in
1)
echo -n "Are you sure you want to clear the contents all the above directories? [y/n] : ";
read yn
if [ $yn != "y" -o $yn != "y" ]
then
  echo "ok Good Bye !!!" ;
   exit;
fi
del_list=(`cat tmp`);
delete;
unset del_list[*];;
2)
  selected_delete;
  delete;;
3)
export flag=1;
break 2>/dev/null ;;
4)exit;;
*)echo "Invalid entry"; clear_contents;;
esac
}
clear_contents;
else
echo -e "Sufficient space available. Space $actual_avail_Gb avaliable while expected is $log_path_min_size_Gb Gigabytes \n"
fi
}
top_10;
while [ $flag != 1 ] 2>/dev/null
do
actual_avail=`df -k $log_path | grep "%" | awk {'print $4'}`;
while [ $actual_avail -lt $log_path_min_size ]
do
echo -e "\n \n";
echo "Cleaning the top 10 folders didnt help... Lets do it again..";
top_10;
actual_avail=`df -k $log_path | grep "%" | awk {'print $4'}`;
done
actual_avail_Gb=`df -h $log_path | grep "%" | awk {'print $4'}`;
echo -e "Sufficient space available. Space $actual_avail_Gb avaliable while expected is $log_path_min_size_Gb Gigabytes \n"
break;
done
rm tmp 2>/dev/null;
clear
fi
