#function for ctrl+c handling
ppid=$$
stop_pr () {
	echo 
	echo "Signal Ctrl+C received. Load Script is going down...";
	grep -i "MOM" $load_report_path/${main_load}_OneMinute_Statistics_${t}.log 2>/dev/null | grep -v MOMQUE >/dev/null 2>/dev/null
	mom_occurance=$?;
	if [ $mom_occurance -eq 0 ]
	then
		echo "###############################################"
		echo "MOM was observed. Pls check the logs at $momq_path/$momque";
                echo "###############################################"
                echo "###############################################" >> $load_report_path/Load_Report_$main_load-$t.txt
		echo "MOM was observed. Pls check the logs at $momq_path/$momque" >> $load_report_path/Load_Report_$main_load-$t.txt
                echo "###############################################" >> $load_report_path/Load_Report_$main_load-$t.txt
		echo "MOM was observed. Pls check the logs at $momq_path/$momque" >> $load_report_path/${main_load}_Hourly_Mem_CPU_${t}.csv
		echo "MOM was observed. Pls check the logs at $momq_path/$momque" >> $load_report_path/${main_load}_Minutes_Mem_CPU_${t}.csv
	fi
	echo "Signal Ctrl+C received. Load Script is going down..." >> $load_report_path/Load_Report_$main_load-$t.txt
        echo "" >> $load_report_path/Load_Report_$main_load-$t.txt
	echo "================================" >> $load_report_path/Load_Report_$main_load-$t.txt
	echo "Load ended at $(date)" >> $load_report_path/Load_Report_$main_load-$t.txt
	echo "================================" >> $load_report_path/Load_Report_$main_load-$t.txt
        cat .lockfile 2>/dev/null &
        echo > .lockfile
	rm -rf .lockfile	
        echo "the pids are ${exec_order[@]} "
	for i in "${exec_order[@]}"
	do
  		for j in {1..90}
  		do
  			eval m=\$product_name_$j
    			if [ "$i" == "$m" ]
    			then
				eval total_instances=\${inital_inst_pid_$j[@]};
				echo "Bringing down all the instances of the product $m...."; 
				echo "Process ids: $total_instances";
				kill -2 $total_instances 2>/dev/null
                kill -9 $total_instances 2>/dev/null
			fi
		done
	done

	for i in `ps -ef| awk '$3 == '${ppid}' { print $2 }'`
	do
		echo "Stopping the child process $i";
		kill -9 $i 2>/dev/null
	done
	echo "Bringing down the main script $0 with process id: $ppid";
	kill -2 $ppid;
        kill -9 $ppid;
}

rm -rf .lockfile
mkfifo .lockfile

stop_load () {
cmd=`cat .lockfile`
if [ "$cmd" == "end" ]
then
   rm -rf .lockfile
