#overlap handling function
overlap_handling () {

echo -n "What do you want to perform?
1. kill the running application
2. Exit

Press the corresponding number [1/2] : "

read yb ;
echo  -e "\n \n" >> $load_report_path/Load_Report_$main_load-$t.txt
