echo "entered value is $yb ";
case $yb in
"1") overlap_inst_pid=`ptree | grep -v grep | grep -w "$1" | awk {'print $1'}`;
  echo -e "Killing  $1 with process id $overlap_inst_pid \n \n";
  echo -e "Killing  $1 with process id $overlap_inst_pid \n \n" >> $load_report_path/Load_Report_$main_load-$t.txt 
  kill -9 $overlap_inst_pid;;
"2") echo -e "\n \n \n Press Ctrl+c to exit "; while true; do echo "Press Ctrl+c to exit"; sleep 10; done;;
*) echo -e "invalid entry \n \n "; overlap_handling;;
esac
}


