				  echo "Note: If Ctrl+C is not working then press ctrl+d and then hit ctrl+c ";
                                  echo "#################################";
				  echo "Error occured... No process id found for instance $instance" >> $load_report_path/Load_Report_$main_load-$t.txt
				  echo "Script will not proceed further." >> $load_report_path/Load_Report_$main_load-$t.txt 
                                  sleep 5
                                done
                        fi
                        restart_count=`expr $restart_count + 1`;
              		if [ -z "$tmid" ];
              		then
 				sleep 5;
		   		restart_instance_empty_pid;
              		else
                   		echo "Restart was successful";
              		fi
	   		fi
	   }
	  restart_instance_empty_pid;
          echo  "Process id of $i instance $instance is: $tmid";
	  echo  "Process id of $i instance $instance is: $tmid" >> $load_report_path/Load_Report_$main_load-$t.txt
          cd $instance_path;
         # ./$instance_start > /dev/null &
          cd $curr_path;

          sleep 2;
       done
       break;
    fi
  done
n=`expr $n + 1`;
done


#Log handling

delete_log () {
	count=`ls -Ftr | grep -v '/' | egrep ".log|.tdr" | wc -l`
	count1=`expr $count - $keep_files`;
	while [ $count1 -gt 0 ]
	do
		ls -Frt | egrep ".log|.tdr" | grep -v '/' | head -"$count1" | xargs rm -rf 2>/dev/null
		echo "log files deleted from the path $instance_log1 ";
                count=`ls -Ftr | grep -v '/' | egrep ".log|.tdr" | wc -l`;
		count1=`expr $count - $keep_files`;
	done
}

move_logs () {
        count=`ls -Ftr | grep -v '/' | egrep ".log|.tdr" | wc -l`
        count1=`expr $count - $keep_files`;
        while [ $count1 -gt 0 ]
        do
                ftbm=`ls -Frt | egrep ".log|.tdr" | grep -v '/' | head -"$count1"` 
		echo -e "\nFile(s) :  ";
		echo -e "========";
		for each_files in $ftbm
		do
		  printf "$each_files" 
		done
                echo -e "\nare being moved: \nFrom: $instance_log1 \nTo: $instance_move_log_to1 \n";
		mv  $ftbm $instance_move_log_to1
                count=`ls -Ftr | grep -v '/' | egrep ".log|.tdr" | wc -l`;
                count1=`expr $count - $keep_files`;
        done
}


gzip_log () {
        count=`ls -Ftr | grep -v '/' | egrep ".log|.tdr" | wc -l`;
	count1=`expr $count - $keep_unzip_files`;
	while [ $count1 -gt 0 ]
	do
		tbz=`ls -Frt | grep -v '/' | grep -v gz | head -"$count1"`;
		for filename in $tbz
		do
			[[ -d Gzip ]] || mkdir Gzip
			mv $filename Gzip
			cd Gzip
			gzip $filename &
			cd ..
			echo "gzipped the file: $filename from the path $instance_log1 "
		done
                count=`ls -Ftr | grep -v '/' | egrep ".log|.tdr" | wc -l`;
		count1=`expr $count - $keep_unzip_files`;
	done
}



log_handling () {
	while true
	do
        sleep 5;
	n1=1;
	for i1 in "${exec_order[@]}"
	do
		for j1 in {1..90}
		do
			eval m1=\$product_name_$j1
			if [ "$i1" == "$m1" ]
			then
				o1=${nof_inst[$n1]};
				for (( o1=1; o1<=${nof_inst[$n1]}; o1++ ))
				do
					eval instance1=\${product_$j1[$o1]}; 
					eval instance_log1=\${product_log_$j1[$o1]};   
                                        eval instance_move_log_to1=\${product_move_log_to_$j1[$o1]};
					cd $instance_log1;
					if [ ${log_flag[$n1]} -eq 1 ]
					then 
						delete_log;
					elif [ ${log_flag[$n1]} -eq 2 ]
					then
						gzip_log;
                                        elif [ ${log_flag[$n1]} -eq 3 ]
                                        then
                                                move_logs;
					else
						:
					fi
				cd $curr_path
				sleep 2;
				done
				break;
			fi
		done
		n1=`expr $n1 + 1`;
	done

	done
}

