                ps -lyef | egrep -i "$instance2|UID" | egrep -v 'grep|vi'| nawk '$3=="PID" { "date '+%Y-%m-%d_%H:%M:%S'" | getline d ; close("date") } { print d,$0 }' | tr -s ' ' ',' | grep -w $instance2 | cut -d, -f1,3-5,9-10,14-16 >> $load_report_path/${1}_Minutes_Ps_Mem_${t}.csv
