                                      echo "Date_time,UID,PID,PPID,RSS,SZ,TIME,CMD" >> $load_report_path/${m1}_Hourly_Ps_Mem_${t}.csv
                                      echo "Date_time,PID,USERNAME,SIZE,RSS,STATE,PRI,NICE,TIME,CPU,PROCESS/NLWP" >> $load_report_path/${m1}_Hourly_Prstat_Cpu_Mem_${t}.csv
