while true
do

 n=1;
for i in "${exec_order[@]}"
do
  for j in {1..90}
  do
  eval m=\$product_name_$j
    if [ "$i" == "$m" ]
    then
       for (( o=1; o<=${nof_inst[$n]}; o++ ))
       do
          eval instance=\${product_$j[$o]}; #echo $instance;
          eval instance_path=\${product_path_$j[$o]}; #echo $instance_path;
          eval instance_start=\${product_start_$j[$o]}; #echo $instance_start;
          eval instance_log=\${product_log_$j[$o]}; #echo $instance_log;
          eval instance_logical_name=\${product_logicalname_$j[$o]}; #echo $instance_logical_name;
          live_tmp=(`ptree | grep -v grep | grep -w "$instance" | awk {'print $1'}`);
          eval live_pid_$j[$o]=\$live_tmp;
          eval inital_pid=\${inital_inst_pid_$j[$o]};
          live_pid=$live_tmp;
          if [ $inital_pid -eq $live_tmp ] 2>/dev/null
          then
              echo "product $i instance $instance is alive with pid: $live_pid";
          else
              echo "product $i instance $instance is alive with pid: $live_pid";
              echo "Oops instance $instance is dead................"; echo ;
	      echo -e "\n \n" >> $load_report_path/Load_Report_$main_load-$t.txt
              echo "Instance $instance is dead at $(date)" >> $load_report_path/Load_Report_$main_load-$t.txt

	      #Saving the logs
	      sos_time=$(date +"%m-%d-%Y-%T")
	      mkdir $load_report_path/SOS_Logs_$sos_time
	      echo "copying the last $sos_logs log files to the directory SOS_Logs_$sos_time  " | tee -a  $load_report_path/Load_Report_$main_load-$t.txt
	      cpath=`pwd`;
	      cd $instance_log;
	      cp `ls -rtl | grep -v '^d' | tail -$sos_logs | awk {'print $9'}` $load_report_path/SOS_Logs_$sos_time 
	      echo "Logs are successfully copied";
	      cd $cpath;
	      if [ $restart_flag -eq 1 ]
	      then 
			:
	      else
			echo "Application went down..." | tee -a $load_report_path/Load_Report_$main_load-$t.txt
			echo " No restart flag enabled... Hit Ctrl+C to exit" | tee -a $load_report_path/Load_Report_$main_load-$t.txt
			while true; do sleep 10; done 
	      fi

              echo "Restarting instance $instance for product $i";
              echo "Restarting instance $instance for product $i" >> $load_report_path/Load_Report_$main_load-$t.txt
	      sleep $lag;
              cd $instance_path;
              ./$instance_start > /dev/null &
              cd $curr_path;
              delay 5;
              live_pid=`ptree | grep -v grep | grep -w "$instance" | awk {'print $1'}`;
              eval inital_inst_pid_$j[$o]=$live_pid;
              echo "$instance for product $i is now up and running with process id: $live_pid ";
              echo "$instance for product $i is now up and running at $(date) with process id: $live_pid " >> $load_report_path/Load_Report_$main_load-$t.txt
          fi

          sleep 2;
       done
       break;
    fi
  done
  echo "========================================================================";
